package com.spai.portal.task.service;
import java.time.OffsetDateTime;import java.util.*;import java.util.stream.Collectors;import com.spai.portal.common.*;import com.spai.portal.task.domain.*;import com.spai.portal.task.repository.*;import org.springframework.dao.OptimisticLockingFailureException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TaskService {private static final Set<String>STATUSES=new HashSet<String>(Arrays.asList("待创建","进行中","已完成"));private final DeliveryTaskRepository tasks;private final TaskProgressRepository progress;private final TaskProgressHistoryRepository history;public TaskService(DeliveryTaskRepository tasks,TaskProgressRepository progress,TaskProgressHistoryRepository history){this.tasks=tasks;this.progress=progress;this.history=history;}
 @Transactional(readOnly=true)public Map<String,Object>list(Map<String,String>f,int page,int size){List<DeliveryTask>all=tasks.filter(v(f,"stage"),v(f,"scene"),v(f,"output"),v(f,"skill"),v(f,"pri"),v(f,"diff"),v(f,"type"));int from=Math.min(page*size,all.size()),to=Math.min(from+size,all.size());List<DeliveryTask>slice=all.subList(from,to);Map<String,List<TaskProgress>>by=progress.findByTaskIdIn(slice.stream().map(DeliveryTask::getId).collect(Collectors.toList())).stream().collect(Collectors.groupingBy(TaskProgress::getTaskId));List<Map<String,Object>>items=slice.stream().map(t->dto(t,by.get(t.getId()))).collect(Collectors.toList());Map<String,Object>result=new LinkedHashMap<String,Object>();result.put("items",items);result.put("page",page);result.put("size",size);result.put("total",all.size());result.put("facets",facets(all));return result;}
 @Transactional public TaskProgress update(String taskId,String teamId,String status,long version,String userId,String userTeam,boolean admin){if(!admin&&!teamId.equals(userTeam))throw BusinessException.forbidden("只能更新所属团队进度");if(!STATUSES.contains(status))throw new BusinessException("INVALID_STATUS","无效的任务状态",org.springframework.http.HttpStatus.BAD_REQUEST);tasks.findById(taskId).orElseThrow(()->BusinessException.notFound("任务不存在"));TaskProgress p=progress.findByTaskIdAndTeamId(taskId,teamId).orElseGet(()->{TaskProgress n=new TaskProgress();n.setId(UUID.randomUUID().toString());n.setTaskId(taskId);n.setTeamId(teamId);return n;});if(p.getLockVersion()!=version)throw BusinessException.conflict("任务进度已被其他用户更新");String old=p.getStatus();p.setStatus(status);p.setUpdatedBy(userId);p.setUpdatedAt(OffsetDateTime.now());try{p=progress.saveAndFlush(p);}catch(OptimisticLockingFailureException e){throw BusinessException.conflict("任务进度已被其他用户更新");}TaskProgressHistory h=new TaskProgressHistory();h.setId(UUID.randomUUID().toString());h.setTaskId(taskId);h.setTeamId(teamId);h.setOldStatus(old);h.setNewStatus(status);h.setChangedBy(userId);history.save(h);return p;}
 private Map<String,Object>dto(DeliveryTask t,List<TaskProgress>ps){Map<String,Object>m=new LinkedHashMap<String,Object>();m.put("uuid",t.getId());m.put("id",t.getExternalId());m.put("stage",t.getStage());m.put("scene",t.getScene());m.put("ai",t.getAi());m.put("desc",t.getDescription());m.put("input",t.getInput());m.put("output",t.getOutput());m.put("type",t.getType());m.put("skill",t.getSkill());m.put("pri",t.getPriority());m.put("diff",t.getDifficulty());m.put("progress",ps==null?Collections.emptyList():ps);return m;}
 private Map<String,Map<String,Long>>facets(List<DeliveryTask>all){Map<String,Map<String,Long>>m=new LinkedHashMap<String,Map<String,Long>>();m.put("stage",count(all,DeliveryTask::getStage));m.put("scene",count(all,DeliveryTask::getScene));m.put("output",count(all,DeliveryTask::getOutput));m.put("skill",count(all,DeliveryTask::getSkill));m.put("pri",count(all,DeliveryTask::getPriority));m.put("diff",count(all,DeliveryTask::getDifficulty));m.put("type",count(all,DeliveryTask::getType));return m;}private Map<String,Long>count(List<DeliveryTask>all,java.util.function.Function<DeliveryTask,String>fn){return all.stream().collect(Collectors.groupingBy(fn,LinkedHashMap::new,Collectors.counting()));}private String v(Map<String,String>m,String k){String s=m.get(k);return s==null||s.trim().isEmpty()?null:s;}}
